modelDefinitions.type:
{
	[K in PlanningOperation]: { operation: K; input: PlanningInput<K> };
}[PlanningOperation]

| { kind: 'image'; version: string; file: string; sha256: Sha256 }
	| { kind: 'notes'; version: string; sha256: Sha256 }
	| { kind: 'approval'; approvalId: string }

| { kind: 'plan-created' }
	| { kind: 'design-added'; version: string }
	| { kind: 'design-approved'; approvalId: string }
	| { kind: 'thread-opened'; threadId: string }
	| { kind: 'message-appended'; threadId: string }
	| { kind: 'other'; path: string }

| { kind: 'health'; path: string }
	| { kind: 'connect'; path: string; hostId: string }
	| { kind: 'pairing'; path: string; hostId: string; pairingId: string; action: PairingAction }

| { type: 'ready'; hostId: string; devices: { deviceId: string; online: boolean }[] }
	| { type: 'device-open'; deviceId: string; connectionId: string }
	| { type: 'device-close'; deviceId: string; connectionId: string }
	| { type: 'packet'; deviceId: string; connectionId: string; packet: SecurePacket }
	| ({ type: 'pairing-request'; pairingId: string } & RelayPairingRequest)
	| { type: 'device-revoked'; deviceId: string }
	| { type: 'ack'; ref: string; ok: boolean; error?: string }

| { type: 'packet'; deviceId: string; connectionId: string; packet: SecurePacket }
	| { type: 'pairing-open'; ref: string; pairingId: string; expiresAt: string }
	/** `challenge` names the one request the host approved; an approval without it is refused. */
	| {
			type: 'pairing-approve';
			ref: string;
			pairingId: string;
			deviceId: string;
			sealed: string;
			challenge: string;
	  }
	| { type: 'pairing-deny'; ref: string; pairingId: string }
	| { type: 'pairing-close'; ref: string; pairingId: string }
	| { type: 'device-revoke'; ref: string; deviceId: string }
	| { type: 'device-drop'; deviceId: string; connectionId: string; code: number }

| { kind: 'grant'; grant: RemoteGrant }
	| { kind: 'revoked' }
	| { kind: 'host'; state: 'suspending' | 'locked' | 'unlocked' }
	| { kind: 'remote-status'; status: RemoteHostStatus }
	| { kind: 'resync' }

configValues.value:
process.env.HARNESS_PICKER_PREVIEW_URL
		? undefined
		: {
				command: preview,
				cwd: root,
				url: `${origin}/preview`,
				timeout: 180_000,
				// A verification tests the preview of its own snapshot, never one already running.
				reuseExistingServer: !process.env.HARNESS_VERIFY
			}

modelDefinitions.type:
| {
			kind: 'cases';
			/** Calls of one symbol, or the one input and output a test observed end to end. */
			source: 'invocations' | 'observation';
			symbol: string | null;
			cases: ExplorerArtifactCase[];
	  }
	| { kind: 'gap'; why: string }

